247	diff --git a/firmware/src/hacks/fireworkx_single.c b/firmware/src/hacks/fireworkx_single.c
248	new file mode 100644
249	index 0000000..282e002
250	--- /dev/null
251	+++ b/firmware/src/hacks/fireworkx_single.c
252	@@ -0,0 +1,82 @@
253	+/* Builds the unmodified fireworkx.c in single precision (the ESP32-S3's FPU is
254	+ * single-precision only, so `double` maths runs in software), with its decimal
255	+ * literals made floats at build time (tools/float_literals.py), or `0.5 * x`
256	+ * would stay software double. Every particle of every shell is moved in
257	+ * double each frame.
258	+ *
259	+ * It also renders at 1/FIREWORKX_SCALE of the width and height (hacks/
260	+ * lowrez_put.h): the glow blur, the flash pass, the conversion to RGB565 and
261	+ * the 4-byte-a-pixel buffers are full-frame walks over PSRAM, 330 ms a frame
262	+ * at 466 by 466 (7.7 fps at a scale of 2, 11 at 3, 12.4 at 4). The picture is
263	+ * already a soft glow. */
264	+#include <math.h>
265	+#include <stdio.h>
266	+#include <stdlib.h>
267	+#include <string.h>
268	+
269	+#include "screenhack.h"
270	+
271	+#ifndef FIREWORKX_SCALE
272	+#define FIREWORKX_SCALE 3
273	+#endif
274	+/* The sparks a shell throws (upstream: 500 at a window about 1024 wide), and
275	+ * how many of its four shells are ever fired. See tools/fireworkx_patch.py. */
276	+#ifndef FIREWORKX_PIXCOUNT
277	+#define FIREWORKX_PIXCOUNT 120
278	+#endif
279	+#ifndef FIREWORKX_SHELLS
280	+#define FIREWORKX_SHELLS 2
281	+#endif
282	+/* The width it renders at, over the 1024 it is tuned for. */
283	+#define FIREWORKX_SIZE \
284	+  ((float)(466 / FIREWORKX_SCALE - (466 / FIREWORKX_SCALE) % 4) / 1024.0f)
285	+#define LOWREZ_SCALE FIREWORKX_SCALE
286	+#include "hacks/lowrez_put.h"
287	+
288	+#include "hacks/single_precision.h"
289	+#include "hacks/single_frand.h"
290	+
291	+#define XGetWindowAttributes lowrez_get_attributes
292	+#define XPutImage lowrez_put_image
293	+
294	+#undef XSCREENSAVER_MODULE
295	+#define XSCREENSAVER_MODULE(CLASS, PREFIX)
296	+#undef M_PI
297	+#define M_PI 3.14159265358979323846f
298	+
299	+/* Below 24 bits a pixel, resize() gives the image a buffer of its own, and
300	+ * upstream's free sets `data` to NULL before XDestroyImage (it assumes the
301	+ * image shares the render buffer, as it does at 24 bits): 48 KB lost each
302	+ * time Fireworkx stops. */
303	+#define fireworkx_free fireworkx_free_upstream
304	+#define fireworkx_init fireworkx_init_upstream
305	+#include "fireworkx_floatlit.c"
306	+#undef fireworkx_free
307	+#undef fireworkx_init
308	+
309	+/* It always runs four shells (the count is baked into its SSE layout), and a
310	+ * shell that never fires throws no sparks and no flash. */
311	+static void *fireworkx_init(Display *dpy, Window window) {
312	+  struct state *st = (struct state *)fireworkx_init_upstream(dpy, window);
313	+  if (!st) return st;
314	+  for (unsigned n = FIREWORKX_SHELLS; n < SHELLCOUNT; n++) {
315	+    fireshell *fs = &st->fireshell_array[n];
316	+    fs->life = 0x7FFFFFFF;
317	+    fs->mortar_fired = 0;
318	+    fs->flash_r = fs->flash_g = fs->flash_b = 0.0f;
319	+    for (unsigned k = 0; k < FIREWORKX_PIXCOUNT; k++) fs->fpix[k].burn = 0;
320	+  }
321	+  return st;
322	+}
323	+
324	+static void fireworkx_free(Display *dpy, Window window, void *closure) {
325	+  struct state *st = (struct state *)closure;
326	+  if (st->xim && st->xim->data != (char *)st->palaka2) {
327	+    free(st->xim->data);
328	+    st->xim->data = NULL;
329	+  }
330	+  fireworkx_free_upstream(dpy, window, closure);
331	+}
332	+
333	+const HackEntry fireworkx_hack = {"Fireworkx", fireworkx_defaults, fireworkx_init,
334	+                                  fireworkx_draw, fireworkx_free, NULL, NULL};
335	diff --git a/firmware/src/hacks/float_polygon.h b/firmware/src/hacks/float_polygon.h
336	new file mode 100644
337	index 0000000..fee58c7
338	--- /dev/null
339	+++ b/firmware/src/hacks/float_polygon.h
340	@@ -0,0 +1,153 @@
341	+#ifndef HACKS_FLOAT_POLYGON_H
342	+#define HACKS_FLOAT_POLYGON_H
343	+
344	+#include <math.h>
345	+#include <stdint.h>
346	+#include <stdlib.h>
347	+
348	+#include "core/canvas.h"
349	+#include "x11shim/pixmap.h"
350	+#include "x11shim/xshim.h"
351	+
352	+/* Fills any polygon even-odd (a self-crossing outline leaves a hole), in
353	+ * float, for a hack whose wrapper maps XFillPolygon onto it. The shim's
354	+ * canvas_fill_polygon divides in double for every edge on every row, which the
355	+ * S3 does in software. This keeps an edge table sorted by starting row and
356	+ * steps each edge's x by its slope, so there is no division per row.
357	+ *
358	+ * A pixel is filled when its centre is inside, as the shim does it. Edges
359	+ * crossing exactly at a half pixel can round to the neighbouring pixel. */
360	+typedef struct {
361	+  float x, slope;
362	+  int y0, y1; /* the edge crosses rows y0 <= y < y1 */
363	+} FloatEdge;
364	+
365	+static int float_edge_order(const void *a, const void *b) {
366	+  const FloatEdge *ea = *(const FloatEdge *const *)a, *eb = *(const FloatEdge *const *)b;
367	+  return (ea->y0 > eb->y0) - (ea->y0 < eb->y0);
368	+}
369	+
370	+/* One row's span [xa, xb] mixed with what is there. The canvas holds byte
371	+ * swapped RGB565, so each pixel is unswapped, and all three channels are mixed
372	+ * at once: spreading a pixel's fields apart (red at bit 11, blue at bit 0,
373	+ * green at bit 21, with room between them) lets one multiply weight them all,
374	+ * `alpha` parts in 32 of the new colour and the rest of the old. Each field's
375	+ * sum fits its own bit range and the shift drops the low bits, so the result
376	+ * is the per-channel (new * alpha + old * (32 - alpha)) / 32, rounded down. */
377	+#define FLOAT_FIELDS 0x07E0F81Fu
378	+
379	+static void float_blend_span(Canvas *c, int xa, int xb, int y, uint16_t color, int alpha) {
380	+  if (y < 0 || y >= c->h || xb < 0 || xa >= c->w) return;
381	+  if (xa < 0) xa = 0;
382	+  if (xb >= c->w) xb = c->w - 1;
383	+  if (xa > xb) return;
384	+  const uint32_t src = px_swap(color);
385	+  const uint32_t weighted = ((src | (src << 16)) & FLOAT_FIELDS) * (uint32_t)alpha;
386	+  const uint32_t inv = (uint32_t)(32 - alpha);
387	+  uint16_t *row = c->px + (size_t)y * (size_t)c->w;
388	+  for (int x = xa; x <= xb; x++) {
389	+    const uint32_t d = px_swap(row[x]);
390	+    const uint32_t mixed = ((weighted + ((d | (d << 16)) & FLOAT_FIELDS) * inv) >> 5) & FLOAT_FIELDS;
391	+    row[x] = px_swap((uint16_t)(mixed | (mixed >> 16)));
392	+  }
393	+  canvas_mark_dirty(c, xa, y, xb - xa + 1, 1);
394	+}
395	+
396	+/* As float_fill_polygon, but the colour is mixed in: `alpha` is in 32nds,
397	+ * 32 opaque and 0 nothing. */
398	+static void float_fill_polygon_alpha(Canvas *c, const XPoint *pts, int n, uint16_t color, int alpha) {
399	+  if (!pts || n < 3 || alpha <= 0) return;
400	+  if (alpha > 32) alpha = 32;
401	+  FloatEdge stack_edges[128];
402	+  FloatEdge *edges = stack_edges;
403	+  const FloatEdge *stack_order[128];
404	+  const FloatEdge **order = stack_order;
405	+  const FloatEdge *stack_active[128];
406	+  const FloatEdge **active = stack_active;
407	+  float stack_xs[128];
408	+  float *xs = stack_xs;
409	+  FloatEdge **heap = NULL;
410	+  if (n > 128) {
411	+    heap = (FloatEdge **)malloc((size_t)n * (sizeof(FloatEdge) + 3 * sizeof(void *) + sizeof(float)));
412	+    if (!heap) return;
413	+    edges = (FloatEdge *)heap;
414	+    order = (const FloatEdge **)(edges + n);
415	+    active = order + n;
416	+    xs = (float *)(active + n);
417	+  }
418	+  int ne = 0, ymin = INT32_MAX, ymax = INT32_MIN;
419	+  for (int i = 0, j = n - 1; i < n; j = i++) {
420	+    int xa = pts[j].x, ya = pts[j].y, xb = pts[i].x, yb = pts[i].y;
421	+    if (ya == yb) continue;
422	+    if (ya > yb) {
423	+      const int tx = xa, ty = ya;
424	+      xa = xb, ya = yb, xb = tx, yb = ty;
425	+    }
426	+    FloatEdge *e = &edges[ne++];
427	+    e->slope = (float)(xb - xa) / (float)(yb - ya);
428	+    e->y0 = ya;
429	+    e->y1 = yb;
430	+    e->x = (float)xa + 0.5f * e->slope; /* at the centre of row ya */
431	+    if (ya < ymin) ymin = ya;
432	+    if (yb > ymax) ymax = yb;
433	+  }
434	+  if (ne >= 2) {
435	+    for (int i = 0; i < ne; i++) order[i] = &edges[i];
436	+    qsort(order, (size_t)ne, sizeof(order[0]), float_edge_order);
437	+    int y = ymin < 0 ? 0 : ymin;
438	+    const int last = ymax > c->h ? c->h : ymax;
439	+    int next = 0, na = 0;
440	+    for (; y < last; y++) {
441	+      while (next < ne && order[next]->y0 <= y) {
442	+        FloatEdge *e = (FloatEdge *)order[next++];
443	+        if (e->y0 < y) e->x += e->slope * (float)(y - e->y0);
444	+        active[na++] = e;
445	+      }
446	+      int nx = 0;
447	+      for (int k = 0; k < na;) {
448	+        FloatEdge *e = (FloatEdge *)active[k];
449	+        if (y >= e->y1) {
450	+          active[k] = active[--na];
451	+          continue;
452	+        }
453	+        float v = e->x;
454	+        e->x += e->slope;
455	+        int m = nx++;
456	+        while (m > 0 && xs[m - 1] > v) {
457	+          xs[m] = xs[m - 1];
458	+          m--;
459	+        }
460	+        xs[m] = v;
461	+        k++;
462	+      }
463	+      for (int k = 0; k + 1 < nx; k += 2) {
464	+        const int xa = (int)ceilf(xs[k] - 0.5f);
465	+        const int xb = (int)ceilf(xs[k + 1] - 0.5f) - 1;
466	+        if (xb >= xa) {
467	+          if (alpha >= 32)
468	+            canvas_fill_rect(c, xa, y, xb - xa + 1, 1, color);
469	+          else
470	+            float_blend_span(c, xa, xb, y, color, alpha);
471	+        }
472	+      }
473	+    }
474	+  }
475	+  free(heap);
476	+}
477	+
478	+static void float_fill_polygon(Canvas *c, const XPoint *pts, int n, uint16_t color) {
479	+  float_fill_polygon_alpha(c, pts, n, color, 32);
480	+}
481	+
482	+/* XFillPolygon's arguments, for a wrapper to `#define XFillPolygon` onto: the
483	+ * shape and mode are ignored, as the shim's are. A bitmap or None draws
484	+ * nothing. */
485	+static int float_x_fill_polygon(Display *dpy, Drawable d, GC gc, XPoint *pts,
486	+                                int n, int shape, int mode) {
487	+  (void)shape, (void)mode;
488	+  Canvas *c = xshim_target(dpy, d);
489	+  if (c) float_fill_polygon(c, pts, n, (uint16_t)gc->foreground);
490	+  return 0;
491	+}
492	+
493	+#endif
