522	+/* spline.h must come in before `double` becomes `float`: the hack includes it
523	+ * too, but the include guard then keeps this copy, and spline.c is built with
524	+ * doubles. Seen through the macro, the control arrays are float*, spline.c
525	+ * reads them as double*, and every blob becomes garbage. */
526	+#include "spline.h"
527	+#include "hacks/float_polygon.h"
528	+#include "hacks/span_erase.h"
529	+#include "hacks/single_precision.h"
530	+#include "hacks/single_frand.h"
531	+
532	+static Pixmap goop_create_pixmap(Display *dpy, Drawable d, unsigned int w,
533	+                                 unsigned int h, unsigned int depth) {
534	+  if (depth == 1) return (XCreatePixmap)(dpy, d, w, h, depth);
535	+  return (Pixmap)XSHIM_WINDOW;
536	+}
537	+
538	+static int goop_free_pixmap(Display *dpy, Pixmap p) {
539	+  return p == (Pixmap)XSHIM_WINDOW ? 0 : (XFreePixmap)(dpy, p);
540	+}
541	+
542	+static int goop_copy_area(Display *dpy, Drawable src, Drawable dst, GC gc,
543	+                          int sx, int sy, unsigned int w, unsigned int h,
544	+                          int dx, int dy) {
545	+  if (src == dst) return 0;
546	+  return (XCopyArea)(dpy, src, dst, gc, sx, sy, w, h, dx, dy);
547	+}
548	+
549	+#define XCreatePixmap goop_create_pixmap
550	+#define XFreePixmap goop_free_pixmap
551	+#define XCopyArea goop_copy_area
552	+
553	+#undef XSCREENSAVER_MODULE
554	+#define XSCREENSAVER_MODULE(CLASS, PREFIX)
555	+#define HAVE_JWXYZ
556	+
557	+/* Upstream's jwxyz path gives each layer's colour an alpha of 0xBB (73 percent),
558	+ * so blobs that overlap show through each other. The shim has no per-pixel
559	+ * alpha, so every blob fills with that weight: 23 parts in 32. 32 is opaque. */
560	+#ifndef GOOP_ALPHA
561	+#define GOOP_ALPHA 23
562	+#endif
563	+
564	+/* Each frame clears the window and fills the blobs again, but the blobs cover
565	+ * a fraction of it: erase only where last frame's blobs were (hacks/
566	+ * span_erase.h), for the same picture and 15 ms less of PSRAM writes. */
567	+static SpanTrack goop_spans;
568	+
569	+static int goop_fill_blob(Display *dpy, Drawable d, GC gc, XPoint *pts, int n,
570	+                          int shape, int mode) {
571	+  (void)shape, (void)mode;
572	+  Canvas *c = xshim_target(dpy, d);
573	+  if (c) span_track_note(&goop_spans, pts, n);
574	+  if (c) float_fill_polygon_alpha(c, pts, n, (uint16_t)gc->foreground, GOOP_ALPHA);
575	+  return 0;
576	+}
577	+
578	+#define XFillPolygon goop_fill_blob
579	+
580	+static int goop_fill_rectangle(Display *dpy, Drawable d, GC gc, int x, int y,
581	+                               unsigned int w, unsigned int h) {
582	+  Canvas *c = xshim_target(dpy, d);
583	+  if (c && d == XSHIM_WINDOW && x == 0 && y == 0 && w >= (unsigned int)c->w &&
584	+      h >= (unsigned int)c->h) {
