622	+/* Builds the unmodified loop.c and makes it pick squares or hexagons again at
623	+ * every start. Upstream chooses `local_neighbors` only `if (!local_neighbors)`
624	+ * and never clears it, which is fine when each run is a process but means the
625	+ * first start after a boot fixes the mode until the next one (on the device
626	+ * every boot looked the same).
627	+ *
628	+ * Its transition table is built once, for that mode (8^4 entries for squares,
629	+ * 8^6, about 1 MB, for hexagons), so it is freed with each start and each stop:
630	+ * a table left over from the other mode would be read past its end, and the
631	+ * memory in use at rest would depend on which mode ran last.
632	+ *
633	+ * The static function table is rewritten before main, so the framework starts
634	+ * and stops the hack through these wrappers. */
635	+#include "loop/loop.c"
636	+
637	+static void forget_the_table(void) {
638	+  free(table);
639	+  table = NULL;
640	+}
641	+
642	+static void init_loop_fresh(ModeInfo *mi) {
643	+  forget_the_table();
644	+  local_neighbors = 0;
645	+  init_loop(mi);
646	+}
647	+
648	+static void free_loop_fresh(ModeInfo *mi) {
649	+  free_loop(mi);
650	+  forget_the_table();
651	+}
652	+
653	+__attribute__((constructor)) static void loop_starts_fresh(void) {
654	+  loop_xlockmore_function_table.hack_init = init_loop_fresh;
655	+  loop_xlockmore_function_table.hack_free = free_loop_fresh;
656	+}
657	+
658	+/* For the tests: 4 for squares, 6 for hexagons, 0 before the first start. */
659	+int loop_neighbors_in_use(void) { return local_neighbors; }
660	diff --git a/firmware/src/hacks/lowrez_put.h b/firmware/src/hacks/lowrez_put.h
661	new file mode 100644
662	index 0000000..9af5167
663	--- /dev/null
664	+++ b/firmware/src/hacks/lowrez_put.h
665	@@ -0,0 +1,78 @@
666	+#ifndef HACKS_LOWREZ_PUT_H
667	+#define HACKS_LOWREZ_PUT_H
668	+
669	+#include <stdint.h>
670	+#include <string.h>
671	+
672	+#include "core/canvas.h"
673	+#include "x11shim/pixmap.h"
674	+#include "x11shim/xshim.h"
675	+
676	+/* Lets a hack that renders every pixel of a window-sized image itself run at
677	+ * 1/LOWREZ_SCALE of the width and height: it is told the window is that much
678	+ * smaller, and its XPutImage draws each pixel as a LOWREZ_SCALE square,
679	+ * centred. The image passes cost 1/LOWREZ_SCALE^2 as much, and so does the
680	+ * memory they walk, which is PSRAM. Include it after defining LOWREZ_SCALE,
681	+ * then map XGetWindowAttributes and XPutImage onto these. */
682	+#ifndef LOWREZ_SCALE
683	+#error "define LOWREZ_SCALE before including lowrez_put.h"
684	+#endif
685	+
686	+static int lowrez_get_attributes(Display *dpy, Window w, XWindowAttributes *a) {
687	+  const int ok = (XGetWindowAttributes)(dpy, w, a);
688	+  a->width /= LOWREZ_SCALE;
689	+  a->height /= LOWREZ_SCALE;
690	+  return ok;
691	+}
692	+
693	+/* The image must be 16-bit (ordinary little-endian RGB565, as the hack builds
694	+ * it for a 16-bit visual); anything else draws nothing. */
695	+static int lowrez_put_image(Display *dpy, Drawable d, GC gc, XImage *im,
696	+                            int src_x, int src_y, int dst_x, int dst_y,
697	+                            unsigned int w, unsigned int h) {
698	+  (void)gc;
699	+  Canvas *const c = xshim_target(dpy, d);
700	+  if (!c || !im || !im->data || im->bits_per_pixel != 16) return 0;
701	+  const int64_t S = LOWREZ_SCALE;
702	+  if (src_x < 0 || src_y < 0) return 0;
703	+  if ((int64_t)w > im->width - src_x) w = (unsigned int)(im->width - src_x);
704	+  if ((int64_t)h > im->height - src_y) h = (unsigned int)(im->height - src_y);
705	+  const int64_t ox = ((int64_t)c->w - (int64_t)im->width * S) / 2;
706	+  const int64_t oy = ((int64_t)c->h - (int64_t)im->height * S) / 2;
707	+  int64_t xa = ox + (int64_t)dst_x * S, xb = ox + ((int64_t)dst_x + w) * S;
708	+  if (xa < 0) xa = 0;
709	+  if (xb > c->w) xb = c->w;
710	+  if (xb <= xa) return 0;
711	+  int64_t ya = INT64_MAX, yb = INT64_MIN;
712	+  for (unsigned int j = 0; j < h; j++) {
713	+    const uint8_t *src = (const uint8_t *)im->data +
714	+                         (size_t)(src_y + j) * (size_t)im->bytes_per_line +
715	+                         (size_t)src_x * 2;
716	+    const int64_t y0 = oy + ((int64_t)dst_y + j) * S;
717	+    uint16_t *first = NULL;
718	+    for (int64_t k = 0; k < S; k++) {
719	+      const int64_t y = y0 + k;
720	+      if (y < 0 || y >= c->h) continue;
721	+      uint16_t *row = c->px + (size_t)y * (size_t)c->w;
722	+      if (first) {
723	+        memcpy(row + xa, first + xa, (size_t)(xb - xa) * sizeof(uint16_t));
724	+      } else {
725	+        for (unsigned int i = 0; i < w; i++) {
726	+          const uint16_t v = px_swap((uint16_t)(src[2 * i] | (src[2 * i + 1] << 8)));
727	+          const int64_t x0 = ox + ((int64_t)dst_x + i) * S;
728	+          for (int64_t kk = 0; kk < S; kk++) {
729	+            const int64_t x = x0 + kk;
730	+            if (x >= xa && x < xb) row[x] = v;
731	+          }
732	+        }
733	+        first = row;
734	+      }
735	+      if (y < ya) ya = y;
736	+      if (y + 1 > yb) yb = y + 1;
737	+    }
738	+  }
739	+  if (yb > ya) canvas_mark_dirty(c, (int)xa, (int)ya, (int)(xb - xa), (int)(yb - ya));
740	+  return 0;
741	+}
742	+
743	+#endif
