830	diff --git a/firmware/src/hacks/span_erase.h b/firmware/src/hacks/span_erase.h
831	new file mode 100644
832	index 0000000..a79cdee
833	--- /dev/null
834	+++ b/firmware/src/hacks/span_erase.h
835	@@ -0,0 +1,66 @@
836	+#ifndef HACKS_SPAN_ERASE_H
837	+#define HACKS_SPAN_ERASE_H
838	+
839	+#include <stdint.h>
840	+
841	+#include "core/canvas.h"
842	+#include "x11shim/xshim.h"
843	+
844	+/* For a hack that clears the whole window and redraws it every frame, when what
845	+ * it draws covers only part of it: clearing 466 by 466 pixels is about 15 ms of
846	+ * PSRAM writes. The wrapper notes each polygon it fills (its bounding box, row
847	+ * by row), and the next frame's "clear" erases only those, so the canvas ends
848	+ * up the same as a full clear. */
849	+#define SPAN_TRACK_ROWS 480
850	+
851	+typedef struct {
852	+  int16_t lo[SPAN_TRACK_ROWS], hi[SPAN_TRACK_ROWS]; /* lo > hi: nothing noted */
853	+  int primed;                                       /* the first erase has run */
854	+} SpanTrack;
855	+
856	+static void span_track_reset(SpanTrack *t) {
857	+  for (int y = 0; y < SPAN_TRACK_ROWS; y++) {
858	+    t->lo[y] = INT16_MAX;
859	+    t->hi[y] = -1;
860	+  }
861	+  t->primed = 0;
862	+}
863	+
864	+/* Notes the rows a polygon touches and the columns it spans there. */
865	+static void span_track_note(SpanTrack *t, const XPoint *pts, int n) {
866	+  if (!pts || n <= 0) return;
867	+  int xmin = pts[0].x, xmax = pts[0].x, ymin = pts[0].y, ymax = pts[0].y;
868	+  for (int i = 1; i < n; i++) {
869	+    if (pts[i].x < xmin) xmin = pts[i].x;
870	+    if (pts[i].x > xmax) xmax = pts[i].x;
871	+    if (pts[i].y < ymin) ymin = pts[i].y;
872	+    if (pts[i].y > ymax) ymax = pts[i].y;
873	+  }
874	+  if (xmin < 0) xmin = 0;
875	+  if (ymin < 0) ymin = 0;
876	+  if (ymax >= SPAN_TRACK_ROWS) ymax = SPAN_TRACK_ROWS - 1;
877	+  if (xmax < xmin) return;
878	+  for (int y = ymin; y <= ymax; y++) {
879	+    if (xmin < t->lo[y]) t->lo[y] = (int16_t)xmin;
880	+    if (xmax > t->hi[y]) t->hi[y] = (int16_t)xmax;
881	+  }
882	+}
883	+
884	+/* The first call, and every call on a canvas taller than the tracker, clears
885	+ * the lot; later ones erase what was noted since the last call, then forget it. */
886	+static void span_track_erase(Canvas *c, SpanTrack *t, uint16_t colour) {
887	+  if (!t->primed || c->h > SPAN_TRACK_ROWS) {
888	+    canvas_fill_rect(c, 0, 0, c->w, c->h, colour);
889	+    t->primed = c->h <= SPAN_TRACK_ROWS;
890	+  } else {
891	+    for (int y = 0; y < c->h; y++)
892	+      if (t->lo[y] <= t->hi[y])
893	+        canvas_fill_rect(c, t->lo[y], y, t->hi[y] - t->lo[y] + 1, 1, colour);
894	+  }
895	+  for (int y = 0; y < SPAN_TRACK_ROWS; y++) {
896	+    t->lo[y] = INT16_MAX;
