diff --git a/firmware/src/hacks/fireworkx_single.c b/firmware/src/hacks/fireworkx_single.c
new file mode 100644
index 0000000..282e002
--- /dev/null
+++ b/firmware/src/hacks/fireworkx_single.c
@@ -0,0 +1,82 @@
+/* Builds the unmodified fireworkx.c in single precision (the ESP32-S3's FPU is
+ * single-precision only, so `double` maths runs in software), with its decimal
+ * literals made floats at build time (tools/float_literals.py), or `0.5 * x`
+ * would stay software double. Every particle of every shell is moved in
+ * double each frame.
+ *
+ * It also renders at 1/FIREWORKX_SCALE of the width and height (hacks/
+ * lowrez_put.h): the glow blur, the flash pass, the conversion to RGB565 and
+ * the 4-byte-a-pixel buffers are full-frame walks over PSRAM, 330 ms a frame
+ * at 466 by 466 (7.7 fps at a scale of 2, 11 at 3, 12.4 at 4). The picture is
+ * already a soft glow. */
+#include <math.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+
+#include "screenhack.h"
+
+#ifndef FIREWORKX_SCALE
+#define FIREWORKX_SCALE 3
+#endif
+/* The sparks a shell throws (upstream: 500 at a window about 1024 wide), and
+ * how many of its four shells are ever fired. See tools/fireworkx_patch.py. */
+#ifndef FIREWORKX_PIXCOUNT
+#define FIREWORKX_PIXCOUNT 120
+#endif
+#ifndef FIREWORKX_SHELLS
+#define FIREWORKX_SHELLS 2
+#endif
+/* The width it renders at, over the 1024 it is tuned for. */
+#define FIREWORKX_SIZE \
+  ((float)(466 / FIREWORKX_SCALE - (466 / FIREWORKX_SCALE) % 4) / 1024.0f)
+#define LOWREZ_SCALE FIREWORKX_SCALE
+#include "hacks/lowrez_put.h"
+
+#include "hacks/single_precision.h"
+#include "hacks/single_frand.h"
+
+#define XGetWindowAttributes lowrez_get_attributes
+#define XPutImage lowrez_put_image
+
+#undef XSCREENSAVER_MODULE
+#define XSCREENSAVER_MODULE(CLASS, PREFIX)
+#undef M_PI
+#define M_PI 3.14159265358979323846f
+
+/* Below 24 bits a pixel, resize() gives the image a buffer of its own, and
+ * upstream's free sets `data` to NULL before XDestroyImage (it assumes the
+ * image shares the render buffer, as it does at 24 bits): 48 KB lost each
+ * time Fireworkx stops. */
+#define fireworkx_free fireworkx_free_upstream
+#define fireworkx_init fireworkx_init_upstream
+#include "fireworkx_floatlit.c"
+#undef fireworkx_free
+#undef fireworkx_init
+
+/* It always runs four shells (the count is baked into its SSE layout), and a
+ * shell that never fires throws no sparks and no flash. */
+static void *fireworkx_init(Display *dpy, Window window) {
+  struct state *st = (struct state *)fireworkx_init_upstream(dpy, window);
+  if (!st) return st;
+  for (unsigned n = FIREWORKX_SHELLS; n < SHELLCOUNT; n++) {
+    fireshell *fs = &st->fireshell_array[n];
+    fs->life = 0x7FFFFFFF;
+    fs->mortar_fired = 0;
+    fs->flash_r = fs->flash_g = fs->flash_b = 0.0f;
+    for (unsigned k = 0; k < FIREWORKX_PIXCOUNT; k++) fs->fpix[k].burn = 0;
+  }
+  return st;
+}
+
+static void fireworkx_free(Display *dpy, Window window, void *closure) {
+  struct state *st = (struct state *)closure;
+  if (st->xim && st->xim->data != (char *)st->palaka2) {
+    free(st->xim->data);
+    st->xim->data = NULL;
+  }
+  fireworkx_free_upstream(dpy, window, closure);
+}
+
+const HackEntry fireworkx_hack = {"Fireworkx", fireworkx_defaults, fireworkx_init,
+                                  fireworkx_draw, fireworkx_free, NULL, NULL};
diff --git a/firmware/src/hacks/float_polygon.h b/firmware/src/hacks/float_polygon.h
new file mode 100644
index 0000000..fee58c7
--- /dev/null
+++ b/firmware/src/hacks/float_polygon.h
@@ -0,0 +1,153 @@
+#ifndef HACKS_FLOAT_POLYGON_H
+#define HACKS_FLOAT_POLYGON_H
+
+#include <math.h>
+#include <stdint.h>
+#include <stdlib.h>
+
+#include "core/canvas.h"
+#include "x11shim/pixmap.h"
+#include "x11shim/xshim.h"
+
+/* Fills any polygon even-odd (a self-crossing outline leaves a hole), in
+ * float, for a hack whose wrapper maps XFillPolygon onto it. The shim's
+ * canvas_fill_polygon divides in double for every edge on every row, which the
+ * S3 does in software. This keeps an edge table sorted by starting row and
+ * steps each edge's x by its slope, so there is no division per row.
+ *
+ * A pixel is filled when its centre is inside, as the shim does it. Edges
+ * crossing exactly at a half pixel can round to the neighbouring pixel. */
+typedef struct {
+  float x, slope;
+  int y0, y1; /* the edge crosses rows y0 <= y < y1 */
+} FloatEdge;
+
+static int float_edge_order(const void *a, const void *b) {
+  const FloatEdge *ea = *(const FloatEdge *const *)a, *eb = *(const FloatEdge *const *)b;
+  return (ea->y0 > eb->y0) - (ea->y0 < eb->y0);
+}
+
+/* One row's span [xa, xb] mixed with what is there. The canvas holds byte
+ * swapped RGB565, so each pixel is unswapped, and all three channels are mixed
+ * at once: spreading a pixel's fields apart (red at bit 11, blue at bit 0,
+ * green at bit 21, with room between them) lets one multiply weight them all,
+ * `alpha` parts in 32 of the new colour and the rest of the old. Each field's
+ * sum fits its own bit range and the shift drops the low bits, so the result
+ * is the per-channel (new * alpha + old * (32 - alpha)) / 32, rounded down. */
+#define FLOAT_FIELDS 0x07E0F81Fu
+
+static void float_blend_span(Canvas *c, int xa, int xb, int y, uint16_t color, int alpha) {
+  if (y < 0 || y >= c->h || xb < 0 || xa >= c->w) return;
+  if (xa < 0) xa = 0;
+  if (xb >= c->w) xb = c->w - 1;
+  if (xa > xb) return;
+  const uint32_t src = px_swap(color);
+  const uint32_t weighted = ((src | (src << 16)) & FLOAT_FIELDS) * (uint32_t)alpha;
+  const uint32_t inv = (uint32_t)(32 - alpha);
+  uint16_t *row = c->px + (size_t)y * (size_t)c->w;
+  for (int x = xa; x <= xb; x++) {
+    const uint32_t d = px_swap(row[x]);
+    const uint32_t mixed = ((weighted + ((d | (d << 16)) & FLOAT_FIELDS) * inv) >> 5) & FLOAT_FIELDS;
+    row[x] = px_swap((uint16_t)(mixed | (mixed >> 16)));
+  }
+  canvas_mark_dirty(c, xa, y, xb - xa + 1, 1);
+}
+
+/* As float_fill_polygon, but the colour is mixed in: `alpha` is in 32nds,
+ * 32 opaque and 0 nothing. */
+static void float_fill_polygon_alpha(Canvas *c, const XPoint *pts, int n, uint16_t color, int alpha) {
+  if (!pts || n < 3 || alpha <= 0) return;
+  if (alpha > 32) alpha = 32;
+  FloatEdge stack_edges[128];
+  FloatEdge *edges = stack_edges;
+  const FloatEdge *stack_order[128];
+  const FloatEdge **order = stack_order;
+  const FloatEdge *stack_active[128];
+  const FloatEdge **active = stack_active;
+  float stack_xs[128];
+  float *xs = stack_xs;
+  FloatEdge **heap = NULL;
+  if (n > 128) {
+    heap = (FloatEdge **)malloc((size_t)n * (sizeof(FloatEdge) + 3 * sizeof(void *) + sizeof(float)));
+    if (!heap) return;
+    edges = (FloatEdge *)heap;
+    order = (const FloatEdge **)(edges + n);
+    active = order + n;
+    xs = (float *)(active + n);
+  }
+  int ne = 0, ymin = INT32_MAX, ymax = INT32_MIN;
+  for (int i = 0, j = n - 1; i < n; j = i++) {
+    int xa = pts[j].x, ya = pts[j].y, xb = pts[i].x, yb = pts[i].y;
+    if (ya == yb) continue;
+    if (ya > yb) {
+      const int tx = xa, ty = ya;
+      xa = xb, ya = yb, xb = tx, yb = ty;
+    }
+    FloatEdge *e = &edges[ne++];
+    e->slope = (float)(xb - xa) / (float)(yb - ya);
+    e->y0 = ya;
+    e->y1 = yb;
+    e->x = (float)xa + 0.5f * e->slope; /* at the centre of row ya */
+    if (ya < ymin) ymin = ya;
+    if (yb > ymax) ymax = yb;
+  }
+  if (ne >= 2) {
+    for (int i = 0; i < ne; i++) order[i] = &edges[i];
+    qsort(order, (size_t)ne, sizeof(order[0]), float_edge_order);
+    int y = ymin < 0 ? 0 : ymin;
+    const int last = ymax > c->h ? c->h : ymax;
+    int next = 0, na = 0;
+    for (; y < last; y++) {
+      while (next < ne && order[next]->y0 <= y) {
+        FloatEdge *e = (FloatEdge *)order[next++];
+        if (e->y0 < y) e->x += e->slope * (float)(y - e->y0);
+        active[na++] = e;
+      }
+      int nx = 0;
+      for (int k = 0; k < na;) {
+        FloatEdge *e = (FloatEdge *)active[k];
+        if (y >= e->y1) {
+          active[k] = active[--na];
+          continue;
+        }
+        float v = e->x;
+        e->x += e->slope;
+        int m = nx++;
+        while (m > 0 && xs[m - 1] > v) {
+          xs[m] = xs[m - 1];
+          m--;
+        }
+        xs[m] = v;
+        k++;
+      }
+      for (int k = 0; k + 1 < nx; k += 2) {
+        const int xa = (int)ceilf(xs[k] - 0.5f);
+        const int xb = (int)ceilf(xs[k + 1] - 0.5f) - 1;
+        if (xb >= xa) {
+          if (alpha >= 32)
+            canvas_fill_rect(c, xa, y, xb - xa + 1, 1, color);
+          else
+            float_blend_span(c, xa, xb, y, color, alpha);
+        }
+      }
+    }
+  }
+  free(heap);
+}
+
+static void float_fill_polygon(Canvas *c, const XPoint *pts, int n, uint16_t color) {
+  float_fill_polygon_alpha(c, pts, n, color, 32);
+}
+
+/* XFillPolygon's arguments, for a wrapper to `#define XFillPolygon` onto: the
+ * shape and mode are ignored, as the shim's are. A bitmap or None draws
+ * nothing. */
+static int float_x_fill_polygon(Display *dpy, Drawable d, GC gc, XPoint *pts,
+                                int n, int shape, int mode) {
+  (void)shape, (void)mode;
+  Canvas *c = xshim_target(dpy, d);
+  if (c) float_fill_polygon(c, pts, n, (uint16_t)gc->foreground);
+  return 0;
+}
+
+#endif
diff --git a/firmware/src/hacks/goop_direct.c b/firmware/src/hacks/goop_direct.c
new file mode 100644
index 0000000..e33f884
--- /dev/null
+++ b/firmware/src/hacks/goop_direct.c
@@ -0,0 +1,106 @@
+/* Builds the unmodified goop.c with HAVE_JWXYZ defined after the framework
+ * headers, which selects the code that draws each layer as filled polygons in
+ * order. The other path needs X colour planes and GXclear with a plane mask,
+ * which the canvas (RGB565, no spare bits) cannot give.
+ *
+ * Single precision (the S3's FPU is single-precision only, so `double` maths
+ * runs in software) with decimal literals made floats at build time, and the
+ * blobs' polygons filled in float (hacks/float_polygon.h): the shim's fill
+ * divides in double for every edge on every row.
+ *
+ * Upstream draws each frame into a window-sized pixmap and copies it to the
+ * window. The canvas is only pushed once the step is done, so nothing can tear:
+ * the pixmap is the window itself, and the copy is skipped (a full-frame
+ * PSRAM copy and 434 KB less memory). A one-bit pixmap (its xor mode) stays a
+ * real one. */
+#include <math.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+
+#include "screenhack.h"
+
+/* spline.h must come in before `double` becomes `float`: the hack includes it
+ * too, but the include guard then keeps this copy, and spline.c is built with
+ * doubles. Seen through the macro, the control arrays are float*, spline.c
+ * reads them as double*, and every blob becomes garbage. */
+#include "spline.h"
+#include "hacks/float_polygon.h"
+#include "hacks/span_erase.h"
+#include "hacks/single_precision.h"
+#include "hacks/single_frand.h"
+
+static Pixmap goop_create_pixmap(Display *dpy, Drawable d, unsigned int w,
+                                 unsigned int h, unsigned int depth) {
+  if (depth == 1) return (XCreatePixmap)(dpy, d, w, h, depth);
+  return (Pixmap)XSHIM_WINDOW;
+}
+
+static int goop_free_pixmap(Display *dpy, Pixmap p) {
+  return p == (Pixmap)XSHIM_WINDOW ? 0 : (XFreePixmap)(dpy, p);
+}
+
+static int goop_copy_area(Display *dpy, Drawable src, Drawable dst, GC gc,
+                          int sx, int sy, unsigned int w, unsigned int h,
+                          int dx, int dy) {
+  if (src == dst) return 0;
+  return (XCopyArea)(dpy, src, dst, gc, sx, sy, w, h, dx, dy);
+}
+
+#define XCreatePixmap goop_create_pixmap
+#define XFreePixmap goop_free_pixmap
+#define XCopyArea goop_copy_area
+
+#undef XSCREENSAVER_MODULE
+#define XSCREENSAVER_MODULE(CLASS, PREFIX)
+#define HAVE_JWXYZ
+
+/* Upstream's jwxyz path gives each layer's colour an alpha of 0xBB (73 percent),
+ * so blobs that overlap show through each other. The shim has no per-pixel
+ * alpha, so every blob fills with that weight: 23 parts in 32. 32 is opaque. */
+#ifndef GOOP_ALPHA
+#define GOOP_ALPHA 23
+#endif
+
+/* Each frame clears the window and fills the blobs again, but the blobs cover
+ * a fraction of it: erase only where last frame's blobs were (hacks/
+ * span_erase.h), for the same picture and 15 ms less of PSRAM writes. */
+static SpanTrack goop_spans;
+
+static int goop_fill_blob(Display *dpy, Drawable d, GC gc, XPoint *pts, int n,
+                          int shape, int mode) {
+  (void)shape, (void)mode;
+  Canvas *c = xshim_target(dpy, d);
+  if (c) span_track_note(&goop_spans, pts, n);
+  if (c) float_fill_polygon_alpha(c, pts, n, (uint16_t)gc->foreground, GOOP_ALPHA);
+  return 0;
+}
+
+#define XFillPolygon goop_fill_blob
+
+static int goop_fill_rectangle(Display *dpy, Drawable d, GC gc, int x, int y,
+                               unsigned int w, unsigned int h) {
+  Canvas *c = xshim_target(dpy, d);
+  if (c && d == XSHIM_WINDOW && x == 0 && y == 0 && w >= (unsigned int)c->w &&
+      h >= (unsigned int)c->h) {
+    span_track_erase(c, &goop_spans, (uint16_t)gc->foreground);
+    return 0;
+  }
+  return (XFillRectangle)(dpy, d, gc, x, y, w, h);
+}
+
+#define XFillRectangle goop_fill_rectangle
+#undef M_PI
+#define M_PI 3.14159265358979323846f
+
+#define goop_init goop_init_upstream
+#include "goop_floatlit.c"
+#undef goop_init
+
+static void *goop_init(Display *dpy, Window window) {
+  span_track_reset(&goop_spans);
+  return goop_init_upstream(dpy, window);
+}
+
+const HackEntry goop_hack = {"Goop", goop_defaults, goop_init, goop_draw,
+                             goop_free, NULL, NULL};
