diff --git a/firmware/src/hacks/loop_direct.c b/firmware/src/hacks/loop_direct.c
new file mode 100644
index 0000000..a20d2d4
--- /dev/null
+++ b/firmware/src/hacks/loop_direct.c
@@ -0,0 +1,38 @@
+/* Builds the unmodified loop.c and makes it pick squares or hexagons again at
+ * every start. Upstream chooses `local_neighbors` only `if (!local_neighbors)`
+ * and never clears it, which is fine when each run is a process but means the
+ * first start after a boot fixes the mode until the next one (on the device
+ * every boot looked the same).
+ *
+ * Its transition table is built once, for that mode (8^4 entries for squares,
+ * 8^6, about 1 MB, for hexagons), so it is freed with each start and each stop:
+ * a table left over from the other mode would be read past its end, and the
+ * memory in use at rest would depend on which mode ran last.
+ *
+ * The static function table is rewritten before main, so the framework starts
+ * and stops the hack through these wrappers. */
+#include "loop/loop.c"
+
+static void forget_the_table(void) {
+  free(table);
+  table = NULL;
+}
+
+static void init_loop_fresh(ModeInfo *mi) {
+  forget_the_table();
+  local_neighbors = 0;
+  init_loop(mi);
+}
+
+static void free_loop_fresh(ModeInfo *mi) {
+  free_loop(mi);
+  forget_the_table();
+}
+
+__attribute__((constructor)) static void loop_starts_fresh(void) {
+  loop_xlockmore_function_table.hack_init = init_loop_fresh;
+  loop_xlockmore_function_table.hack_free = free_loop_fresh;
+}
+
+/* For the tests: 4 for squares, 6 for hexagons, 0 before the first start. */
+int loop_neighbors_in_use(void) { return local_neighbors; }
diff --git a/firmware/src/hacks/lowrez_put.h b/firmware/src/hacks/lowrez_put.h
new file mode 100644
index 0000000..9af5167
--- /dev/null
+++ b/firmware/src/hacks/lowrez_put.h
@@ -0,0 +1,78 @@
+#ifndef HACKS_LOWREZ_PUT_H
+#define HACKS_LOWREZ_PUT_H
+
+#include <stdint.h>
+#include <string.h>
+
+#include "core/canvas.h"
+#include "x11shim/pixmap.h"
+#include "x11shim/xshim.h"
+
+/* Lets a hack that renders every pixel of a window-sized image itself run at
+ * 1/LOWREZ_SCALE of the width and height: it is told the window is that much
+ * smaller, and its XPutImage draws each pixel as a LOWREZ_SCALE square,
+ * centred. The image passes cost 1/LOWREZ_SCALE^2 as much, and so does the
+ * memory they walk, which is PSRAM. Include it after defining LOWREZ_SCALE,
+ * then map XGetWindowAttributes and XPutImage onto these. */
+#ifndef LOWREZ_SCALE
+#error "define LOWREZ_SCALE before including lowrez_put.h"
+#endif
+
+static int lowrez_get_attributes(Display *dpy, Window w, XWindowAttributes *a) {
+  const int ok = (XGetWindowAttributes)(dpy, w, a);
+  a->width /= LOWREZ_SCALE;
+  a->height /= LOWREZ_SCALE;
+  return ok;
+}
+
+/* The image must be 16-bit (ordinary little-endian RGB565, as the hack builds
+ * it for a 16-bit visual); anything else draws nothing. */
+static int lowrez_put_image(Display *dpy, Drawable d, GC gc, XImage *im,
+                            int src_x, int src_y, int dst_x, int dst_y,
+                            unsigned int w, unsigned int h) {
+  (void)gc;
+  Canvas *const c = xshim_target(dpy, d);
+  if (!c || !im || !im->data || im->bits_per_pixel != 16) return 0;
+  const int64_t S = LOWREZ_SCALE;
+  if (src_x < 0 || src_y < 0) return 0;
+  if ((int64_t)w > im->width - src_x) w = (unsigned int)(im->width - src_x);
+  if ((int64_t)h > im->height - src_y) h = (unsigned int)(im->height - src_y);
+  const int64_t ox = ((int64_t)c->w - (int64_t)im->width * S) / 2;
+  const int64_t oy = ((int64_t)c->h - (int64_t)im->height * S) / 2;
+  int64_t xa = ox + (int64_t)dst_x * S, xb = ox + ((int64_t)dst_x + w) * S;
+  if (xa < 0) xa = 0;
+  if (xb > c->w) xb = c->w;
+  if (xb <= xa) return 0;
+  int64_t ya = INT64_MAX, yb = INT64_MIN;
+  for (unsigned int j = 0; j < h; j++) {
+    const uint8_t *src = (const uint8_t *)im->data +
+                         (size_t)(src_y + j) * (size_t)im->bytes_per_line +
+                         (size_t)src_x * 2;
+    const int64_t y0 = oy + ((int64_t)dst_y + j) * S;
+    uint16_t *first = NULL;
+    for (int64_t k = 0; k < S; k++) {
+      const int64_t y = y0 + k;
+      if (y < 0 || y >= c->h) continue;
+      uint16_t *row = c->px + (size_t)y * (size_t)c->w;
+      if (first) {
+        memcpy(row + xa, first + xa, (size_t)(xb - xa) * sizeof(uint16_t));
+      } else {
+        for (unsigned int i = 0; i < w; i++) {
+          const uint16_t v = px_swap((uint16_t)(src[2 * i] | (src[2 * i + 1] << 8)));
+          const int64_t x0 = ox + ((int64_t)dst_x + i) * S;
+          for (int64_t kk = 0; kk < S; kk++) {
+            const int64_t x = x0 + kk;
+            if (x >= xa && x < xb) row[x] = v;
+          }
+        }
+        first = row;
+      }
+      if (y < ya) ya = y;
+      if (y + 1 > yb) yb = y + 1;
+    }
+  }
+  if (yb > ya) canvas_mark_dirty(c, (int)xa, (int)ya, (int)(xb - xa), (int)(yb - ya));
+  return 0;
+}
+
+#endif
