+void test_a_16_bit_image_is_two_bytes_a_pixel_and_keeps_16_bits(void) {
+  XImage *im = XCreateImage(dpy, NULL, 16, ZPixmap, 0, NULL, 5, 3, 8, 0);
+  TEST_ASSERT_NOT_NULL(im);
+  TEST_ASSERT_EQUAL_INT(16, im->bits_per_pixel);
