+static spline *square_spline(void) {
+  spline *sp = make_spline(4);
+  static const double xs[4] = {0, 10, 10, 0}, ys[4] = {0, 0, 10, 10};
+  for (int i = 0; i < 4; i++) {
+    sp->control_x[i] = xs[i];
+    sp->control_y[i] = ys[i];
+  }
+  return sp;
+}
