		free(st->mem2);
		free(st->mem1);
                st->xim = 0;
	}
	st->xim = XCreateImage(st->dpy, xwa.visual, xwa.depth, ZPixmap, 0, 0,
	                       st->width, st->height, 8, 0);
	if (!st->xim) return;

